namespace FolderScope {
 public static class Exporter {
  public static string[] Headers {get{return new[]{"Name","Size (bytes)","Size on disk (bytes)","Count","Percent","Modified (local)","Owner","Full Path","Information"}.Select(L.T).ToArray();}}
  public static string[] Cells(ReportRow r){return new[]{r.DisplayName,r.Size.ToString(),r.Allocated.ToString(),r.Count.ToString(),r.Percent.ToString("0.00",System.Globalization.CultureInfo.InvariantCulture),Util.Date(r.Modified),r.Owner??"",r.Path??"",L.Value(r.Extra??"")};}
  private static string Csv(string x){x=x??"";return "\""+x.Replace("\"","\"\"")+"\"";}
  public static string ToCsv(IEnumerable<ReportRow> rows,bool tabs){string sep=tabs?"\t":",";var b=new StringBuilder();b.AppendLine(string.Join(sep,Headers));foreach(var r in rows){string[] cells=Cells(r);for(int i=0;i<cells.Length;i++)if((i==0||i>=5)&&cells[i].Length>0&&"=-+@\t\r".IndexOf(cells[i][0])>=0)cells[i]="'"+cells[i];b.AppendLine(string.Join(sep,cells.Select(Csv)));}return b.ToString();}
  public static void Save(string file,string title,List<ReportRow> rows){string ext=Path.GetExtension(file).ToLowerInvariant();switch(ext){case ".html":Html(file,title,rows);break;case ".xlsx":Excel(file,title,rows);break;case ".pdf":Pdf(file,title,rows);break;case ".xml":Xml(file,title,rows);break;default:File.WriteAllText(file,ToCsv(rows,ext==".txt"||ext==".tsv"),new UTF8Encoding(true));break;}}
  private static string Escape(string s){return SecurityElement.Escape(s??"");}
  private static void Html(string file,string title,List<ReportRow> rows){using(var w=new StreamWriter(file,false,new UTF8Encoding(false))){w.Write("<!doctype html><html><head><meta charset=\"utf-8\"><title>"+Escape(title)+"</title><style>body{font:14px Segoe UI,Arial;margin:32px;color:#263444}h1{color:#0078b5}table{border-collapse:collapse;width:100%}th,td{padding:8px;border-bottom:1px solid #dce3e9;text-align:left;overflow-wrap:anywhere}th{background:#e9f4fb;position:sticky;top:0}tr:nth-child(even){background:#f7f9fb}</style></head><body><h1>"+Escape(title)+"</h1><p>FolderScope · "+DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss")+" · "+rows.Count+(L.Chinese?" 条记录":" rows")+"</p><table><thead><tr>");foreach(string h in Headers)w.Write("<th>"+Escape(h)+"</th>");w.Write("</tr></thead><tbody>");foreach(var r in rows){w.Write("<tr>");foreach(var c in Cells(r))w.Write("<td>"+Escape(c)+"</td>");w.Write("</tr>");}w.Write("</tbody></table></body></html>");}}
  private static void Xml(string file,string title,List<ReportRow> rows){using(var w=XmlWriter.Create(file,new XmlWriterSettings{Indent=true,Encoding=new UTF8Encoding(false)})){w.WriteStartElement("FolderScopeReport");w.WriteAttributeString("title",title);w.WriteAttributeString("captured",DateTime.UtcNow.ToString("o"));foreach(var r in rows){w.WriteStartElement("Row");var vals=Cells(r);for(int i=0;i<vals.Length;i++)w.WriteElementString(new[]{"Name","Size","Allocated","Count","Percent","Modified","Owner","Path","Information"}[i],vals[i]);w.WriteEndElement();}w.WriteEndElement();}}
  private static void Put(ZipArchive zip,string path,string content){var e=zip.CreateEntry(path,CompressionLevel.Optimal);using(var w=new StreamWriter(e.Open(),new UTF8Encoding(false)))w.Write(content);}
  private static void Excel(string file,string title,List<ReportRow> rows){
   if(rows.Count>1048575)throw new InvalidOperationException("Excel worksheets support at most 1,048,575 data rows. Export CSV instead.");
   using(var f=File.Create(file))using(var z=new ZipArchive(f,ZipArchiveMode.Create)){
    Put(z,"[Content_Types].xml","<?xml version=\"1.0\" encoding=\"utf-8\"?><Types xmlns=\"http://schemas.openxmlformats.org/package/2006/content-types\"><Default Extension=\"rels\" ContentType=\"application/vnd.openxmlformats-package.relationships+xml\"/><Default Extension=\"xml\" ContentType=\"application/xml\"/><Override PartName=\"/xl/workbook.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml\"/><Override PartName=\"/xl/worksheets/sheet1.xml\" ContentType=\"application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml\"/></Types>");
    Put(z,"_rels/.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument\" Target=\"xl/workbook.xml\"/></Relationships>");
    Put(z,"xl/workbook.xml","<workbook xmlns=\"http://schemas.openxmlformats.org/spreadsheetml/2006/main\" xmlns:r=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships\"><sheets><sheet name=\"Report\" sheetId=\"1\" r:id=\"rId1\"/></sheets></workbook>");
    Put(z,"xl/_rels/workbook.xml.rels","<Relationships xmlns=\"http://schemas.openxmlformats.org/package/2006/relationships\"><Relationship Id=\"rId1\" Type=\"http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet\" Target=\"worksheets/sheet1.xml\"/></Relationships>");
    using(var stream=z.CreateEntry("xl/worksheets/sheet1.xml",CompressionLevel.Optimal).Open())using(var w=XmlWriter.Create(stream,new XmlWriterSettings{Encoding=new UTF8Encoding(false)})){
     string ns="http://schemas.openxmlformats.org/spreadsheetml/2006/main";w.WriteStartElement("worksheet",ns);w.WriteStartElement("sheetViews");w.WriteStartElement("sheetView");w.WriteAttributeString("workbookViewId","0");w.WriteStartElement("pane");w.WriteAttributeString("ySplit","1");w.WriteAttributeString("topLeftCell","A2");w.WriteAttributeString("state","frozen");w.WriteEndElement();w.WriteEndElement();w.WriteEndElement();
     w.WriteStartElement("cols");for(int i=1;i<=9;i++){w.WriteStartElement("col");w.WriteAttributeString("min",i.ToString());w.WriteAttributeString("max",i.ToString());w.WriteAttributeString("width",i==1?"35":i==8?"65":"22");w.WriteAttributeString("customWidth","1");w.WriteEndElement();}w.WriteEndElement();w.WriteStartElement("sheetData");
     for(int row=0;row<=rows.Count;row++){string[] vals=row==0?Headers:Cells(rows[row-1]);w.WriteStartElement("row");w.WriteAttributeString("r",(row+1).ToString());for(int c=0;c<vals.Length;c++){w.WriteStartElement("c");w.WriteAttributeString("r",((char)('A'+c)).ToString()+(row+1));bool num=row>0&&c>=1&&c<=4;if(num){w.WriteElementString("v",vals[c]);}else{w.WriteAttributeString("t","inlineStr");w.WriteStartElement("is");w.WriteElementString("t",CleanXml(vals[c]));w.WriteEndElement();}w.WriteEndElement();}w.WriteEndElement();}w.WriteEndElement();w.WriteStartElement("autoFilter");w.WriteAttributeString("ref","A1:I"+(rows.Count+1));w.WriteEndElement();w.WriteEndElement();
    }
   }
  }
  private static string CleanXml(string s){var b=new StringBuilder();s=s??"";for(int i=0;i<s.Length;i++){if(char.IsHighSurrogate(s[i])&&i+1<s.Length&&char.IsLowSurrogate(s[i+1])){b.Append(s[i]);b.Append(s[++i]);}else if(XmlConvert.IsXmlChar(s[i]))b.Append(s[i]);}return b.ToString();}
  private static void DrawPage(Graphics g,RectangleF area,string title,List<ReportRow> rows,int start,int count,int page){
   g.Clear(Color.White);using(var heading=new Font("Segoe UI",17,FontStyle.Bold))using(var f=new Font("Segoe UI",9))using(var small=new Font("Segoe UI",8))using(var blue=new SolidBrush(Color.FromArgb(0,120,180))){
    g.DrawString(title,heading,blue,area.X,area.Y);g.DrawString("FolderScope   |   "+DateTime.Now.ToString("yyyy-MM-dd HH:mm")+"   |   Page "+page,small,Brushes.Gray,area.X,area.Y+32);
    float y=area.Y+60;float[] widths={.40f,.13f,.13f,.34f};string[] hdr={L.Chinese?"名称 / 信息":"Name / information",L.T("Size"),L.T("Count"),L.T("Path")};float x=area.X;g.FillRectangle(Brushes.AliceBlue,area.X,y,area.Width,24);for(int c=0;c<4;c++){g.DrawString(hdr[c],f,Brushes.Black,x+4,y+4);x+=area.Width*widths[c];}y+=28;
    for(int n=start;n<Math.Min(start+count,rows.Count);n++){ReportRow r=rows[n];if(n%2==0)g.FillRectangle(Brushes.WhiteSmoke,area.X,y,area.Width,35);string[] vals={r.DisplayName+(string.IsNullOrEmpty(r.Extra)?"":" · "+L.Attributes(r.Extra)),Util.Size(r.Size),r.Count.ToString("N0"),r.Path??""};x=area.X;for(int c=0;c<4;c++){var rect=new RectangleF(x+4,y+3,area.Width*widths[c]-8,32);g.DrawString(vals[c],small,Brushes.Black,rect,new StringFormat{Trimming=StringTrimming.EllipsisCharacter,FormatFlags=StringFormatFlags.LineLimit});x+=area.Width*widths[c];}y+=35;}
   }
  }
  public static PrintDocument Document(string title,List<ReportRow> rows){var d=new PrintDocument();d.DocumentName=title;d.DefaultPageSettings.Landscape=true;int start=0,page=0;d.BeginPrint+=(s,e)=>{start=0;page=0;};d.PrintPage+=(s,e)=>{int count=Math.Max(1,(e.MarginBounds.Height-88)/35);DrawPage(e.Graphics,e.MarginBounds,title,rows,start,count,++page);start+=count;e.HasMorePages=start<rows.Count;};return d;}
  private static void Pdf(string file,string title,List<ReportRow> rows){
   int per=12,pages=Math.Max(1,(rows.Count+per-1)/per);using(var f=File.Create(file)){
    var offsets=new List<long>{0};Action<string> write=t=>{byte[] b=Encoding.ASCII.GetBytes(t);f.Write(b,0,b.Length);};Action<int,string> obj=(id,s)=>{while(offsets.Count<=id)offsets.Add(0);offsets[id]=f.Position;write(id+" 0 obj\n"+s+"\nendobj\n");};write("%PDF-1.4\n");obj(1,"<< /Type /Catalog /Pages 2 0 R >>");obj(2,"<< /Type /Pages /Count "+pages+" /Kids ["+string.Join(" ",Enumerable.Range(0,pages).Select(i=>(3+i*3)+" 0 R"))+"] >>");
    for(int p=0;p<pages;p++){
     int id=3+p*3;byte[] jpeg;using(var bmp=new Bitmap(1684,1190)){using(var g=Graphics.FromImage(bmp)){g.ScaleTransform(2,2);DrawPage(g,new RectangleF(30,28,782,539),title,rows,p*per,per,p+1);}using(var m=new MemoryStream()){bmp.Save(m,ImageFormat.Jpeg);jpeg=m.ToArray();}}
     obj(id,"<< /Type /Page /Parent 2 0 R /MediaBox [0 0 842 595] /Resources << /XObject << /Im "+(id+1)+" 0 R >> >> /Contents "+(id+2)+" 0 R >>");while(offsets.Count<=id+1)offsets.Add(0);offsets[id+1]=f.Position;write((id+1)+" 0 obj\n<< /Type /XObject /Subtype /Image /Width 1684 /Height 1190 /ColorSpace /DeviceRGB /BitsPerComponent 8 /Filter /DCTDecode /Length "+jpeg.Length+" >>\nstream\n");f.Write(jpeg,0,jpeg.Length);write("\nendstream\nendobj\n");string content="q 842 0 0 595 0 0 cm /Im Do Q";obj(id+2,"<< /Length "+content.Length+" >>\nstream\n"+content+"\nendstream");
    }
    long xref=f.Position;write("xref\n0 "+offsets.Count+"\n0000000000 65535 f \n");for(int i=1;i<offsets.Count;i++)write(offsets[i].ToString("0000000000")+" 00000 n \n");write("trailer\n<< /Size "+offsets.Count+" /Root 1 0 R >>\nstartxref\n"+xref+"\n%%EOF");
   }
  }
 }
 public static class FileJobs {
  public static List<string> Normalize(IEnumerable<string> paths){var all=paths.Select(Util.Norm).Distinct(StringComparer.OrdinalIgnoreCase).OrderBy(p=>p.Length).ToList();var result=new List<string>();foreach(string p in all)if(!result.Any(r=>Util.Under(p,r)))result.Add(p);return result;}
  public static void Copy(string src,string dest){if(Directory.Exists(src)){if(Util.Under(dest,src))throw new IOException("Destination cannot be inside source.");if(Directory.Exists(dest)||File.Exists(dest))throw new IOException("Destination already exists: "+dest);CopyDirectory(src,dest);}else{if(new FileInfo(src).Attributes.HasFlag(FileAttributes.ReparsePoint))throw new IOException("Copying reparse points is not supported: "+src);File.Copy(src,dest,false);}}
  private static void CopyDirectory(string src,string dest){if((File.GetAttributes(src)&FileAttributes.ReparsePoint)!=0)throw new IOException("Reparse point encountered: "+src);Directory.CreateDirectory(dest);foreach(string f in Directory.GetFiles(src))Copy(f,Path.Combine(dest,Path.GetFileName(f)));foreach(string d in Directory.GetDirectories(src))CopyDirectory(d,Path.Combine(dest,Path.GetFileName(d)));}
  public static void Archive(IEnumerable<string> paths,string target){var sources=Normalize(paths);foreach(string p in sources)if(Util.Under(target,p))throw new IOException("Archive must be outside selected source folders.");using(var fs=new FileStream(target,FileMode.CreateNew))using(var zip=new ZipArchive(fs,ZipArchiveMode.Create)){var used=new HashSet<string>(StringComparer.OrdinalIgnoreCase);foreach(string p in sources){string name=Path.GetFileName(p.TrimEnd('\\'));if(string.IsNullOrEmpty(name))name="Drive";if(!used.Add(name))throw new IOException("Duplicate archive root name: "+name);Add(zip,p,name);}}}
  private static void Add(ZipArchive zip,string path,string name){if((File.GetAttributes(path)&FileAttributes.ReparsePoint)!=0)throw new IOException("Archive skipped a reparse point: "+path);if(Directory.Exists(path)){zip.CreateEntry(name.TrimEnd('/')+"/");foreach(string child in Directory.EnumerateFileSystemEntries(path))Add(zip,child,name+"/"+Path.GetFileName(child));}else zip.CreateEntryFromFile(path,name,CompressionLevel.Optimal);}
  public static void Audit(string action,string path,string result){File.AppendAllText(Path.Combine(Util.DataDir,"file-operations.log"),DateTime.Now.ToString("o")+"\t"+action+"\t"+path+"\t"+result+Environment.NewLine,new UTF8Encoding(false));}
 }
 public class ScheduledJob {
  public string Name="Daily disk report";public string Paths="";public string Output="";public string Report="Folder details";public string Format="html";public string Frequency="Daily";public DateTime Start=DateTime.Now.AddHours(1);public bool Email;public ScanOptions Options=new ScanOptions();
 }
 public static class Jobs {
  public static string TaskXml(ScheduledJob job,string jobFile){string boundary=job.Start.ToString("yyyy-MM-ddTHH:mm:ss");string trigger=job.Frequency=="Once"?"<TimeTrigger><StartBoundary>"+boundary+"</StartBoundary><Enabled>true</Enabled></TimeTrigger>":"<CalendarTrigger><StartBoundary>"+boundary+"</StartBoundary><Enabled>true</Enabled>"+(job.Frequency=="Weekly"?"<ScheduleByWeek><WeeksInterval>1</WeeksInterval><DaysOfWeek><"+job.Start.DayOfWeek+"/></DaysOfWeek></ScheduleByWeek>":"<ScheduleByDay><DaysInterval>1</DaysInterval></ScheduleByDay>")+"</CalendarTrigger>";return "<?xml version=\"1.0\" encoding=\"UTF-16\"?><Task version=\"1.2\" xmlns=\"http://schemas.microsoft.com/windows/2004/02/mit/task\"><RegistrationInfo><Description>FolderScope scheduled local storage report</Description></RegistrationInfo><Triggers>"+trigger+"</Triggers><Principals><Principal id=\"Author\"><LogonType>InteractiveToken</LogonType><RunLevel>LeastPrivilege</RunLevel></Principal></Principals><Settings><MultipleInstancesPolicy>IgnoreNew</MultipleInstancesPolicy><DisallowStartIfOnBatteries>false</DisallowStartIfOnBatteries><StopIfGoingOnBatteries>false</StopIfGoingOnBatteries><StartWhenAvailable>true</StartWhenAvailable><ExecutionTimeLimit>PT12H</ExecutionTimeLimit></Settings><Actions Context=\"Author\"><Exec><Command>"+SecurityElement.Escape(Application.ExecutablePath)+"</Command><Arguments>--job &quot;"+SecurityElement.Escape(jobFile)+"&quot;</Arguments><WorkingDirectory>"+SecurityElement.Escape(Application.StartupPath)+"</WorkingDirectory></Exec></Actions></Task>";}
  public static string Register(ScheduledJob job){string dir=Path.Combine(Util.DataDir,"jobs");Directory.CreateDirectory(dir);string id=Guid.NewGuid().ToString("N"),file=Path.Combine(dir,id+".xml");AtomicXml.Write(job,file);string xml=TaskXml(job,file);Type type=Type.GetTypeFromProgID("Schedule.Service");dynamic scheduler=Activator.CreateInstance(type);scheduler.Connect();dynamic root=scheduler.GetFolder("\\");string name="FolderScope_"+id;root.RegisterTask(name,xml,6,null,null,3,null);return name;}
  public static void Run(ScheduledJob j){Directory.CreateDirectory(j.Output);var s=new Scanner().Run(j.Paths.Split('|'),j.Options,System.Threading.CancellationToken.None);string basename=Path.Combine(j.Output,"FolderScope-"+DateTime.Now.ToString("yyyyMMdd-HHmmss"));Snapshot.Save(s,basename+".fsscan");if(j.Report!="Snapshot"){var rows=j.Report=="Folder details"?s.Entries.OrderByDescending(e=>e.Size).Select(Reports.Row).ToList():Reports.Build(s,j.Report,0,"Name + size",System.Threading.CancellationToken.None);string report=basename+"."+j.Format;Exporter.Save(report,L.T(j.Report),rows);if(j.Email)Send(AppSettings.Load(),j.Name,report);}if(s.Events.Count>0)File.WriteAllLines(basename+"-events.txt",s.Events.Select(e=>e.Path+"\t"+e.Message));}
  public static void Send(AppSettings settings,string subject,string file){if(string.IsNullOrWhiteSpace(settings.SmtpHost)||string.IsNullOrWhiteSpace(settings.MailTo))throw new InvalidOperationException("Configure SMTP and recipients in Options first.");using(var message=new MailMessage()){message.From=new MailAddress(settings.MailFrom);foreach(string address in settings.MailTo.Split(new[]{';',','},StringSplitOptions.RemoveEmptyEntries))message.To.Add(address.Trim());message.Subject=subject;message.Body="FolderScope storage report. Generated "+DateTime.Now.ToString("yyyy-MM-dd HH:mm:ss");message.Attachments.Add(new Attachment(file));using(var client=new SmtpClient(settings.SmtpHost,settings.SmtpPort)){client.EnableSsl=settings.SmtpSsl;client.Timeout=60000;if(!string.IsNullOrEmpty(settings.SmtpUser))client.Credentials=new NetworkCredential(settings.SmtpUser,settings.Password);client.Send(message);}}}
 }
 public class DiskPoint {public DateTime Time=DateTime.UtcNow;public string Root;public long Total;public long Free;}
 public class DiskHistory {public List<DiskPoint> Points=new List<DiskPoint>();public static DiskHistory Load(){try{return AtomicXml.Read<DiskHistory>(Path.Combine(Util.DataDir,"disk-history.xml"));}catch{return new DiskHistory();}}public void Record(){foreach(var d in DriveInfo.GetDrives().Where(d=>d.DriveType!=DriveType.Network))try{if(d.IsReady){Points.Add(new DiskPoint{Root=d.Name,Total=d.TotalSize,Free=d.AvailableFreeSpace});}}catch{}Points=Points.OrderByDescending(p=>p.Time).Take(5000).ToList();AtomicXml.Write(this,Path.Combine(Util.DataDir,"disk-history.xml"));}}
}
